def main():
    os.makedirs(BASE, exist_ok=True)
    assert set(P.keys()) == set(IDS), (set(P.keys()) ^ set(IDS))
    assert len(P) == 20
    n = 0
    for cid in IDS:
        d = P[cid]
        out = {"case_id": cid, "prediction_text": d["prediction_text"],
               "basis": d["basis"], "confidence": d["confidence"], "trigger": d["trigger"]}
        with open(os.path.join(BASE, cid + ".json"), "w", encoding="utf-8") as f:
            json.dump(out, f, ensure_ascii=False, indent=1)
        n += 1
    assert n == 20
    cm = sum(1 for c in IDS if P[c]["trigger"]["changed_main"])
    ru = sum(1 for c in IDS if P[c]["trigger"]["reserve_used"])
    dp = sum(1 for c in IDS if P[c]["trigger"]["disputed"])
    print("written:", n)
    print("changed_main:", cm, "reserve_used:", ru, "disputed:", dp)

if __name__ == "__main__":
    main()
